DO $$
DECLARE
  rec RECORD;
  cur_status VARCHAR(20);
  cur_denial_code VARCHAR(10);
BEGIN
  FOR rec IN SELECT * FROM claim_actions ORDER BY action_id LOOP
    SELECT status, denial_reason_code INTO cur_status, cur_denial_code
    FROM claim_lines
    WHERE claim_line_id = rec.claim_line_id;

    IF rec.action_type = 'SUBMIT' AND cur_status = 'draft' THEN
      UPDATE claim_lines
      SET status = 'submitted'
      WHERE claim_line_id = rec.claim_line_id;
    ELSIF rec.action_type = 'DENY' AND cur_status = 'submitted' THEN
      UPDATE claim_lines
      SET status = 'denied', denial_reason_code = rec.reason_code
      WHERE claim_line_id = rec.claim_line_id;
    ELSIF rec.action_type = 'APPEAL' AND cur_status = 'denied' THEN
      UPDATE claim_lines
      SET status = 'appealed'
      WHERE claim_line_id = rec.claim_line_id;
    ELSIF rec.action_type = 'PAY' AND (cur_status = 'submitted' OR cur_status = 'appealed') THEN
      UPDATE claim_lines
      SET status = 'paid'
      WHERE claim_line_id = rec.claim_line_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM claim_lines ORDER BY claim_line_id;
